do $$ begin if to_regclass('"example".core__command_receipt') is not null then drop policy if exists maintenance on "example".core__command_receipt; drop policy if exists maintenance_select on "example".core__command_receipt; drop policy if exists maintenance_delete on "example".core__command_receipt; create policy maintenance_select on "example".core__command_receipt for select using (current_setting('keelwerk.scope', true) = 'namespace'); create policy maintenance_delete on "example".core__command_receipt for delete using (current_setting('keelwerk.scope', true) = 'namespace'); end if; end $$;
